UPDATE "invoice" SET "created_by_service" = "creation"."caller" FROM (SELECT DISTINCT ON ("entity_id") "entity_id", "caller" FROM "ledger_audit_log" WHERE "action" = 'invoice.created' AND "entity_type" = 'invoice' AND "caller" IS NOT NULL ORDER BY "entity_id", "created_at" ASC, "id" ASC) AS "creation" WHERE "creation"."entity_id" = "invoice"."id" AND "invoice"."created_by_service" IS NULL;
